// Pseudo-validator outline
function validate(record) {
  const hasFields = record.deviceId && record.ts && record.correlationId && typeof record.severity === 'number';
  const okSeverity = record.severity >= 0 && record.severity <= 100;
  return hasFields && okSeverity;
}
```

